from pathlib import Path
import json,hashlib
import numpy as np
P=Path(__file__).parent;SEEDS=[11,22,33]
def read(f):return json.loads((P/f).read_text())
def main():
    rows=[];records={}
    for kind in ['normal_ce','normal_kd','direct_ce','direct_kd']:
        for endpoint in (['equal_data'] if kind.startswith('normal') else ['equal_data','equal_cpu']):
            rs=[read(f'{kind}_{s}_{endpoint}.json') for s in SEEDS];records[kind,endpoint]=rs
            values=[r['test']['nll_nats'] for r in rs]
            rows.append(dict(kind=kind,endpoint=endpoint,mean_test_nll=float(np.mean(values)),seed_sd_test_nll=float(np.std(values,ddof=1)),test_nll_by_seed=values,mean_validation_nll=float(np.mean([r['validation']['nll_nats'] for r in rs])),steps=[r['steps'] for r in rs],mean_training_cpu_seconds=float(np.mean([r['training_cpu_seconds'] for r in rs])),mean_training_wall_seconds=float(np.mean([r['training_wall_seconds'] for r in rs])),mean_recipe_cpu_with_teacher=float(np.mean([r['recipe_cpu_including_full_teacher_cache'] for r in rs])),token_exposures=[r['token_exposures'] for r in rs]))
    bootstrap=np.random.default_rng(99719).integers(0,64,(10000,64));contrasts=[]
    pairs=[(('direct_ce',e),('normal_ce','equal_data')) for e in ['equal_data','equal_cpu']]+[(('direct_kd',e),('normal_kd','equal_data')) for e in ['equal_data','equal_cpu']]+[(('direct_kd','equal_data'),('direct_ce','equal_data')),(('normal_kd','equal_data'),('normal_ce','equal_data'))]
    for left,right in pairs:
        a=np.array([r['test']['window_nll_nats'] for r in records[left]]);b=np.array([r['test']['window_nll_nats'] for r in records[right]]);d=(a-b).mean(0)
        contrasts.append(dict(left=left,right=right,mean_difference_nats=float(d.mean()),window_bootstrap_95=np.quantile(d[bootstrap].mean(1),[.025,.975]).tolist(),scope='Conditional on these3trained seeds and64test windows; not a population-level confidence interval over models, datasets or training seeds.'))
    normal=read('accounting_normal.json');block=read('accounting_block.json')
    io=dict(normal_cold_component_read_bytes=normal['cold_component_logical_read_bytes'],block_cold_component_read_bytes=block['cold_component_logical_read_bytes'],normal_warm_body_read_bytes=normal['warm_shared_maps_body_reads'][0]['logical_bytes'],block_warm_body_read_bytes=block['warm_shared_maps_body_reads'][0]['logical_bytes'],normal_weight_write_bytes=normal['updated_trainable_weight_write']['logical_bytes'],block_weight_write_bytes=block['updated_trainable_weight_write']['logical_bytes'],normal_peak_rss_bytes=normal['process_peak_rss_bytes'],block_peak_rss_bytes=block['process_peak_rss_bytes'],normal_saved_tensor_bytes=normal['saved_nonparameter_storage_bytes'],block_saved_tensor_bytes=block['saved_nonparameter_storage_bytes'],normal_matrix_flops=normal['profiled_matrix_operator_flops_per_step'],block_matrix_flops=block['profiled_matrix_operator_flops_per_step'],physical_read_bytes_normal=sum(x['proc_io_delta']['read_bytes'] for x in normal['initial_reads']),physical_read_bytes_block=sum(x['proc_io_delta']['read_bytes'] for x in block['initial_reads']),scope='Separate executed scratch offload probe; primary adaptation runs keep model weights in RAM. Logical read savings do not establish uncached SSD speed or 512B throughput. Cold component means vocabulary maps loaded too, not OS caches flushed. Optimizer state excluded from file-transfer sizes. FLOPs are supported matrix operators, not exhaustive instructions.')
    out=dict(complete=True,untouched_test_nll=read('untouched.json')['test']['nll_nats'],rows=rows,contrasts=contrasts,offload_probe=io,limits=['Small14M model, frozen lexical maps and49,152 training-token exposures per equal-data run','Converted finite4particle log score is not exact implicit diffusion likelihood or perplexity','New evaluation contexts exclude v1 contexts, but use the same benchmark and original pretraining overlap is unknown','Independent partition is not function-preserving; full-depth neutral-adapter check does not establish quality preservation after splitting','Teacher preparation uses the full model once offline over the cached training batches; its cost and storage are reported, not erased','Matrix FLOPs and wall time reported separately; CPU matching is not simultaneous equal-FLOP/data/wall matching','No production changes, no GPU/512B training, no long-context retrieval or autoregressive cache-continuation claim'])
    (P/'summary.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2))
if __name__=='__main__':main()
